  getDb()
    .insert(sessions)
    .values({
      id: newId(),
      userId,
      activeOrgId: null,
      tokenHash,
      expiresAt,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .run();

  return {
    userId,
    email: user.email,
    activeOrgId: null,
