413	/**
414	 * Test double for `@/lib/id` (owner E).
415	 *
416	 * The server suite needs ids that are valid ULIDs *and* reproducible, so a
417	 * failing assertion names the same row on every run. Counter-based rather than
418	 * random for exactly that reason.
419	 */
420	const ULID_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
421	const ULID_LENGTH = 26;
422	
423	let counter = 0;
424	
425	export function newId(): string {
426	  counter += 1;
427	  return encode(counter);
428	}
429	
430	export function isUlid(value: string): boolean {
431	  return (
432	    value.length === ULID_LENGTH &&
433	    [...value].every((char) => ULID_ALPHABET.includes(char.toUpperCase()))
434	  );
435	}
436	
437	export function idFactory(seed: number): () => string {
438	  let local = seed;
439	  return () => {
440	    local += 1;
441	    return encode(local);
442	  };
443	}
444	
445	/** Test-only: rewinds the counter so each file starts from the same ids. */
446	export function resetIds(): void {
447	  counter = 0;
448	}
449	
450	function encode(value: number): string {
451	  let remaining = value;
452	  let out = "";
453	
454	  while (out.length < ULID_LENGTH) {
455	    out = `${ULID_ALPHABET[remaining % 32] ?? "0"}${out}`;
456	    remaining = Math.floor(remaining / 32);
457	  }
458	
459	  return out.slice(-ULID_LENGTH);
460	}
