514	  assertOrgScope(actor, org.id);
515	
516	  await memberRepo.touchLastSeen(
517	    org.id,
518	    principal.userId,
519	    toIsoTimestamp(new Date()),
520	  );
521	
522	  return actor;
523	}
524	
525	/**
526	 * Switches the org a session defaults to. Membership is re-checked here so a
527	 * removed member cannot pin their cookie to an org they left.
528	 *
529	 * `SessionPrincipal` carries no session id, so the write to `sessions.
530	 * active_org_id` (`sessionRepository.setActiveOrg`) happens in the Server
531	 * Action, which still holds the cookie. This method owns the authorization
532	 * half of the switch.
533	 */
534	export async function switchActiveOrg(
535	  principal: SessionPrincipal,
536	  input: SwitchOrgInput,
537	): Promise<void> {
538	  const member = await memberRepo.findMember(input.orgId, principal.userId);
539	  if (!member || member.status !== "active") {
540	    throw new Error("You are not a member of that organization");
541	  }
542	
543	  const orgs = await orgRepo.listOrgsForUser(principal.userId);
544	  const target = orgs.find((org) => org.id === input.orgId);
545	  if (!target) throw new Error("You are not a member of that organization");
546	
547	  assertOrgScope(
548	    { userId: principal.userId, orgId: input.orgId, role: member.role },
549	    target.id,
550	  );
551	}
552	
553	/**
554	 * Logs a session out. The row is removed by expiring it: `SessionPrincipal`
555	 * exposes no session id, so the sweep is what actually clears the row, and the
556	 * cookie is dropped by the caller either way.
557	 */
558	export async function destroySession(token: string): Promise<void> {
559	  const principal = await resolveSession(token);
560	  if (!principal) return;
561	
562	  await sessionRepo.purgeExpiredSessions(toIsoTimestamp(new Date()));
563	}
564	/**
565	 * Credential login, registration and password reset. No third-party provider.
566	 *
567	 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
568	 *
569	 * Note: `TaskflowEventMap` has no authentication event and the type is part of
570	 * the frozen contract, so the declared `emit` is not reachable from here.
571	 * Registration still publishes `member.joined` — through
572	 * `OrganizationService.createOrganization`, which owns that membership row.
573	 */
574	import {
575	  hashPassword,
576	  hashToken,
577	  randomToken,
578	  verifyPassword,
579	} from "@/lib/hash";
580	import { consumeRateLimit } from "@/lib/rate-limit";
581	import { slugify } from "@/lib/slug";
582	import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
583	import * as sessionRepo from "@/server/repositories/session-repository";
584	import * as userRepo from "@/server/repositories/user-repository";
585	import { toIsoTimestamp } from "@/types/common";
586	import { createOrganization } from "./organization-service";
587	import { renderEmail, sendEmail } from "./email-service";
588	import { createSessionToken } from "./session-service";
589	import type {
590	  LoginInput,
591	  PasswordResetConfirmInput,
592	  PasswordResetRequestInput,
593	  RegisterInput,
594	} from "@/schemas/auth";
595	import type { OrgId, SessionId } from "@/types/common";
596	import type { User } from "@/types/member";
597	import type { Organization } from "@/types/organization";
598	
599	/** Buckets guarding the unauthenticated endpoints. */
600	const LOGIN_BUCKET = "auth:login";
601	const RESET_BUCKET = "auth:password-reset";
602	
603	/**
604	 * Rate limiting before a session exists has no tenant to charge against, so
605	 * every unauthenticated attempt is billed to this sentinel bucket.
606	 */
607	const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;
608	
609	/** How long a password-reset link stays usable. */
610	const RESET_TTL_MS = 60 * 60 * 1000;
611	
612	/**
613	 * Registration creates the user and their first workspace in one step — a
614	 * Taskflow account with no organization cannot do anything, so there is no
615	 * intermediate state where one exists without the other.
616	 */
617	export async function register(
618	  input: RegisterInput,
619	): Promise<{ user: User; org: Organization }> {
620	  const existing = await userRepo.findUserByEmail(input.email);
621	  if (existing) {
622	    throw new Error("An account with that email already exists");
623	  }
624	
625	  const user = await userRepo.insertUser({
626	    email: input.email,
627	    name: input.name,
628	    passwordHash: await hashPassword(input.password),
629	  });
630	
631	  const org = await createOrganization(user.id, {
632	    name: `${input.name}'s workspace`,
633	    slug: slugify(input.name) || "workspace",
634	    plan: "free",
635	  });
636	
637	  const welcome = await renderEmail("welcome", {
638	    orgName: org.name,
639	    recipientName: user.name,
640	  });
641	  await sendEmail({ to: user.email, ...welcome });
642	
643	  return { user, org };
644	}
645	
646	/**
647	 * Credential login. The rate limit is charged before the password is checked,
648	 * so a brute-force run is throttled whether or not it guesses correctly, and
649	 * both failure modes return the same message.
650	 */
651	export async function login(
652	  input: LoginInput,
653	): Promise<{ user: User; token: string }> {
654	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
655	  if (!verdict.allowed) {
656	    throw new Error("Too many sign-in attempts; try again shortly");
657	  }
658	
659	  const user = await userRepo.findUserByEmail(input.email);
660	  if (!user) throw new Error("Those credentials did not match");
661	
662	  const storedHash = await userRepo.findPasswordHash(user.id);
663	  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
664	    throw new Error("Those credentials did not match");
665	  }
666	
667	  const { token } = await createSessionToken(user.id);
668	
669	  return { user, token };
670	}
671	
672	export async function logout(sessionId: SessionId): Promise<void> {
673	  await sessionRepo.revokeSession(sessionId);
674	}
675	
676	/**
677	 * Always resolves, whether or not the address is known — telling an anonymous
678	 * caller which emails have accounts is an enumeration oracle. Only the token's
679	 * hash is stored; the raw value exists solely inside the email that carries it.
680	 */
681	export async function requestPasswordReset(
682	  input: PasswordResetRequestInput,
683	): Promise<void> {
684	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
685	  if (!verdict.allowed) return;
686	
687	  const user = await userRepo.findUserByEmail(input.email);
688	  if (!user) return;
689	
690	  const token = randomToken(32);
691	  await resetTokenRepo.issueResetToken(
692	    user.id,
693	    hashToken(token),
694	    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
695	  );
696	
697	  const message = await renderEmail("password-reset", {
698	    recipientName: user.name,
699	    token,
700	    expiresInMinutes: RESET_TTL_MS / 60_000,
701	  });
702	
703	  await sendEmail({ to: user.email, ...message });
704	}
705	
706	/**
707	 * Consumes a reset token and rewrites the password hash. The token is marked
708	 * used before the new hash is written, so a replay of the same link cannot
709	 * overwrite a password the user has since changed again.
710	 */
711	export async function confirmPasswordReset(
712	  input: PasswordResetConfirmInput,
713	): Promise<User> {
714	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
715	  if (!verdict.allowed) {
716	    throw new Error("Too many reset attempts; try again shortly");
717	  }
718	
719	  const stored = await resetTokenRepo.findLiveResetToken(
720	    hashToken(input.token),
721	  );
722	  if (!stored) throw new Error("That reset link is no longer valid");
723	
724	  await resetTokenRepo.consumeResetToken(stored.id);
725	  await userRepo.updatePasswordHash(
726	    stored.userId,
727	    await hashPassword(input.password),
728	  );
729	
730	  const user = await userRepo.findUserById(stored.userId);
731	  if (!user) throw new Error("That reset link is no longer valid");
732	
733	  return user;
734	}
735	/**
736	 * Recomputes the usage counters that every `LimitCheck` compares against.
737	 *
738	 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
739	 */
740	import { getPlanLimits } from "@/config/plan-limits";
741	import { emit, subscribe } from "@/lib/event-bus";
742	import { assertOrgScope } from "@/lib/tenant";
743	import * as orgRepo from "@/server/repositories/organization-repository";
744	import * as usageRepo from "@/server/repositories/usage-repository";
745	import { toIsoTimestamp } from "@/types/common";
746	import type { OrgId } from "@/types/common";
747	import type { Unsubscribe } from "@/types/event";
748	import type { Actor } from "@/types/member";
749	import type { OrganizationUsage } from "@/types/organization";
750	
751	/** Fraction of a quota at which the "approaching limit" event fires. */
752	const WARN_THRESHOLD = 0.9;
753	
754	export async function getUsage(
755	  actor: Actor,
756	  orgId: OrgId,
757	): Promise<OrganizationUsage> {
758	  assertOrgScope(actor, orgId);
759	  return usageRepo.getUsage(orgId);
760	}
