762	/**
763	 * Full recount from the source tables. Called by the rollup job and by every
764	 * event that could have moved a counter — after recounting, the seat and
765	 * project totals are checked against the plan so a breach surfaces as an
766	 * event rather than waiting for the next write to be rejected.
767	 */
768	export async function recomputeUsage(
769	  orgId: OrgId,
770	): Promise<OrganizationUsage> {
771	  const usage = await usageRepo.recomputeUsage(orgId);
772	  const org = await orgRepo.findOrgById(orgId);
773	  if (!org) return usage;
774	
775	  const limits = getPlanLimits(org.plan);
776	
777	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
778	    await emit("billing.limit_exceeded", {
779	      orgId,
780	      actorId: null,
781	      occurredAt: toIsoTimestamp(new Date()),
782	      resource: "seats",
783	      limit: limits.seats,
784	      used: usage.seatsUsed,
785	    });
786	  }
787	
788	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
789	    await emit("billing.limit_exceeded", {
790	      orgId,
791	      actorId: null,
792	      occurredAt: toIsoTimestamp(new Date()),
793	      resource: "projects",
794	      limit: limits.projects,
795	      used: usage.projectsUsed,
796	    });
797	  }
798	
799	  return usage;
800	}
801	
802	/**
803	 * Every event that changes a counted resource nudges the cache. The deltas are
804	 * cheap; the periodic rollup is what corrects any drift they accumulate.
805	 */
806	export function registerUsageListeners(): Unsubscribe {
807	  const offs: Unsubscribe[] = [
808	    subscribe("issue.created", async (payload) => {
809	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
810	    }),
811	    subscribe("issue.archived", async (payload) => {
812	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
813	    }),
814	    subscribe("project.created", async (payload) => {
815	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
816	    }),
817	    subscribe("project.archived", async (payload) => {
818	      await usageRepo.incrementUsage(payload.orgId, {
819	        projectsUsed: -1,
820	        issuesUsed: -payload.issuesArchived,
821	      });
822	    }),
823	    subscribe("member.joined", async (payload) => {
824	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
825	    }),
826	    subscribe("member.removed", async (payload) => {
827	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
828	    }),
829	  ];
830	
831	  return () => {
832	    for (const off of offs) off();
833	  };
834	}
835	/**
836	 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
837	 *
838	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
839	 */
840	import { createHmac } from "node:crypto";
841	import { wouldExceedLimit } from "@/config/plan-limits";
842	import { subscribe } from "@/lib/event-bus";
843	import { isEnabled } from "@/lib/feature-flags";
844	import { randomToken } from "@/lib/hash";
845	import { assertCan } from "@/lib/permissions";
846	import { assertOrgScope } from "@/lib/tenant";
847	import * as orgRepo from "@/server/repositories/organization-repository";
848	import * as webhookRepo from "@/server/repositories/webhook-repository";
849	import { requireFound, webhookResource } from "./_support";
850	import type {
851	  CreateWebhookInput,
852	  DeleteWebhookInput,
853	  UpdateWebhookInput,
854	} from "@/schemas/webhook";
855	import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
856	import type { OrgId } from "@/types/common";
857	import type { Unsubscribe } from "@/types/event";
