859	import type { Actor } from "@/types/member";
860	
861	/** Length in bytes of a generated endpoint signing secret. */
862	const SECRET_BYTES = 32;
863	
864	export async function listWebhooks(
865	  actor: Actor,
866	  orgId: OrgId,
867	): Promise<readonly WebhookEndpointRow[]> {
868	  assertOrgScope(actor, orgId);
869	  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
870	  return webhookRepo.listEndpoints(orgId);
