873	/**
874	 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
875	 * the org's plan, and the plan's endpoint count must have room. A secret is
876	 * minted here and never regenerated — rotating it means deleting the endpoint.
877	 */
878	export async function createWebhook(
879	  actor: Actor,
880	  input: CreateWebhookInput,
881	): Promise<WebhookEndpointRow> {
882	  assertOrgScope(actor, input.orgId);
883	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));
884	
885	  const org = requireFound(
886	    await orgRepo.findOrgById(input.orgId),
887	    "Organization",
888	    input.orgId,
889	  );
890	
891	  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
892	    throw new Error("Outgoing webhooks are not included in this plan");
893	  }
894	
895	  const used = await webhookRepo.countEndpoints(input.orgId);
896	  if (wouldExceedLimit(org.plan, "webhooks", used)) {
897	    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
898	  }
899	
900	  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
901	}
902	
903	export async function updateWebhook(
904	  actor: Actor,
905	  input: UpdateWebhookInput,
906	): Promise<WebhookEndpointRow> {
907	  assertOrgScope(actor, input.orgId);
908	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
909	  return webhookRepo.updateEndpoint(input);
910	}
