912	export async function deleteWebhook(
913	  actor: Actor,
914	  input: DeleteWebhookInput,
915	): Promise<void> {
916	  assertOrgScope(actor, input.orgId);
917	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
918	  await webhookRepo.deleteEndpoint(input.orgId, input.webhookId);
919	}
