921	/**
922	 * HMAC-SHA256 over the raw body, hex encoded. The receiving end recomputes
923	 * this from the same secret — it is the only thing proving the delivery came
924	 * from Taskflow, so the payload string must be signed byte-for-byte as sent.
925	 */
926	export function signPayload(secret: string, payload: string): string {
927	  return createHmac("sha256", secret).update(payload, "utf8").digest("hex");
928	}
929	
930	/**
931	 * Fans domain events out into the delivery table. Each org's endpoints
932	 * declare which event types they want, so an endpoint only ever receives what
