934	 */
935	export function registerWebhookListeners(): Unsubscribe {
936	  const offs: Unsubscribe[] = [
937	    subscribe("webhook.delivery_requested", async (payload) => {
938	      await enqueueForOrg(
939	        payload.orgId,
940	        payload.eventType,
941	        JSON.stringify(payload.payload),
942	      );
943	    }),
944	    subscribe("issue.created", async (payload) => {
945	      await enqueueForOrg(payload.orgId, "issue.created", JSON.stringify(payload));
946	    }),
947	    subscribe("issue.status_changed", async (payload) => {
948	      await enqueueForOrg(
949	        payload.orgId,
950	        "issue.status_changed",
951	        JSON.stringify(payload),
952	      );
953	    }),
954	    subscribe("comment.created", async (payload) => {
955	      await enqueueForOrg(
956	        payload.orgId,
957	        "comment.created",
958	        JSON.stringify(payload),
959	      );
960	    }),
961	    subscribe("billing.plan_changed", async (payload) => {
962	      await enqueueForOrg(
963	        payload.orgId,
964	        "billing.plan_changed",
965	        JSON.stringify(payload),
966	      );
967	    }),
968	  ];
969	
970	  return () => {
971	    for (const off of offs) off();
972	  };
973	}
974	
975	async function enqueueForOrg(
976	  orgId: OrgId,
977	  eventType: string,
978	  payload: string,
979	): Promise<void> {
980	  const endpoints = await webhookRepo.listEndpoints(orgId);
981	
982	  for (const endpoint of endpoints) {
983	    if (!endpoint.enabled) continue;
984	
985	    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
986	    if (!wanted.includes(eventType)) continue;
987	
988	    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
989	  }
990	}
991	
992	function flagContextFor(
993	  actor: Actor,
994	  plan: FlagContext["plan"],
995	  overrides: readonly string[],
996	): FlagContext {
997	  return {
998	    orgId: actor.orgId,
999	    userId: actor.userId,
1000	    plan,
1001	    role: actor.role,
1002	    overrides,
1003	  };
1004	}
1005	/**
1006	 * Builds the daily digest bundle per recipient from unread notifications inside the org's digest window.
1007	 *
1008	 * Must call (do not reimplement): isEnabled, renderEmail
1009	 */
1010	import { isEnabled } from "@/lib/feature-flags";
1011	import { DIGEST_MAX_ENTRIES } from "@/config/constants";
1012	import * as notificationRepo from "@/server/repositories/notification-repository";
1013	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
1014	import * as orgRepo from "@/server/repositories/organization-repository";
1015	import { renderEmail } from "./email-service";
1016	import { buildFlagContext } from "./feature-flag-service";
1017	import type { RenderedEmail } from "@/server/services/email-service";
1018	import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
1019	import type { User } from "@/types/member";
1020	import type { DigestBundle, DigestEntry } from "@/types/notification";
1021	
1022	/** A digest with fewer entries than this is not worth an email. */
1023	const MIN_ENTRIES = 1;
1024	
1025	/**
1026	 * Collects one recipient's unread notifications inside the window. Returns
1027	 * `null` — rather than an empty bundle — when the org's plan does not include
1028	 * the digest, or when there is nothing to say: the caller treats `null` as
1029	 * "send nothing", so a quiet day produces no mail at all.
1030	 */
1031	export async function buildDigest(
1032	  orgId: OrgId,
1033	  recipientId: UserId,
1034	  windowStart: IsoTimestamp,
1035	  windowEnd: IsoTimestamp,
1036	): Promise<DigestBundle | null> {
1037	  const org = await orgRepo.findOrgById(orgId);
1038	  if (!org) return null;
1039	
1040	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
1041	
1042	  const unread = await notificationRepo.listUnreadSince(
1043	    orgId,
1044	    recipientId,
1045	    windowStart,
1046	  );
1047	
1048	  const entries: DigestEntry[] = unread
1049	    .filter((notification) => notification.createdAt <= windowEnd)
1050	    .map((notification) => ({
1051	      notificationId: notification.id,
1052	      kind: notification.kind,
1053	      title: notification.title,
1054	      href: notification.href,
1055	      occurredAt: notification.createdAt,
1056	    }))
1057	    .slice(0, DIGEST_MAX_ENTRIES);
1058	
1059	  if (entries.length < MIN_ENTRIES) return null;
1060	
1061	  return { orgId, recipientId, entries, windowStart, windowEnd };
1062	}
1063	
1064	/**
1065	 * Who gets a digest: everyone who set at least one notification kind to
1066	 * `digestOnly`. Opting into the digest is what suppresses the immediate
1067	 * emails, so the two lists are two views of the same preference.
1068	 */
1069	export async function listDigestRecipients(
1070	  orgId: OrgId,
1071	): Promise<readonly UserId[]> {
1072	  return preferenceRepo.listDigestSubscribers(orgId);
1073	}
1074	
1075	/** Renders one bundle through the shared email pipeline. */
1076	export async function renderDigest(
1077	  bundle: DigestBundle,
1078	  recipient: User,
1079	): Promise<RenderedEmail> {
1080	  return renderEmail("digest", {
1081	    orgId: bundle.orgId,
1082	    recipientName: recipient.name,
1083	    entryCount: bundle.entries.length,
1084	    windowStart: bundle.windowStart,
1085	    windowEnd: bundle.windowEnd,
1086	    headline: bundle.entries[0]?.title ?? "",
1087	  });
1088	}
