export async function restoreOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(restorePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/**
 * Every deleted (archived) org, live ones excluded. Cross-tenant by design:
 * it feeds the retention sweep, which decides which of them are past the
 * grace period.
 */
export async function listDeletedOrgs(): Promise<readonly Organization[]> {
  const rows = getDb()
    .select()
    .from(organizations)
    .where(isNotNull(organizations.archivedAt))
    .all();
  return rows.map(toOrganization);
}

/** Every table whose rows belong to exactly one organization. */
const TENANT_TABLES = [
  members,
  invitations,
  projectMembers,
  projects,
  issueLabels,
  attachments,
  comments,
  issues,
  labels,
  notifications,
  notificationPreferences,
  activityEvents,
  invoices,
  subscriptions,
  webhookDeliveries,
  webhookEndpoints,
  searchIndex,
  rateLimitBuckets,
] as const;

/**
 * Physically removes an organization and every row that belongs to it, in one
 * transaction. User accounts are global and stay; a session that had this org
 * active is left without an active org. The only caller is the retention
 * sweep, once the deletion grace period has closed — there is no undo.
 */
export async function purgeOrg(orgId: OrgId): Promise<void> {
  getDb().transaction((tx) => {
    for (const table of TENANT_TABLES) {
      tx.delete(table).where(eq(table.orgId, orgId)).run();
    }

    tx.delete(organizationUsage)
      .where(eq(organizationUsage.orgId, orgId))
      .run();

    tx.update(sessions)
      .set({ activeOrgId: null })
      .where(eq(sessions.activeOrgId, orgId))
      .run();

    tx.delete(organizations).where(eq(organizations.id, orgId)).run();
  });
}

