/**
 * True once an archived row has been archived for at least `retentionDays`
 * (counted as whole 24h periods) at `now`. A live row is never past retention.
 */
export function isPastRetention(
  row: SoftDeletable,
  retentionDays: number,
  now: Date = new Date(),
): boolean {
  if (row.archivedAt === null) return false;

  const archivedAt = Date.parse(row.archivedAt);
  if (Number.isNaN(archivedAt)) return false;

  return now.getTime() - archivedAt >= retentionDays * MS_PER_DAY;
}

