 * GitHub uses: the caller has to retype the slug.
 *
 * A deleted workspace is kept, inert, for `DELETED_WORKSPACE_RETENTION_DAYS`:
 * nothing is removed here, so `restoreOrganization` can bring all of it back
 * until the retention sweep purges it.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  assertNotArchived("Organization", org.id, org);

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  const deleted = await orgRepo.archiveOrg(input.orgId);

  await announce("organization.deleted", actorEnvelope(actor), deleted);

  return deleted;
}

/**
 * Brings a deleted workspace back while its grace period is still open.
 *
 * Takes a bare `userId`: no `Actor` can be resolved for a deleted workspace,
 * so the caller's membership is read here and the `org:restore` check runs
 * against an actor assembled from that row.
 *
 * A workspace that does not exist, one the caller has no membership in, and
 * one whose grace period has closed are the same `NotFoundError` on purpose —
 * past the window the workspace is gone whether or not the purge has run, and
 * distinguishing the cases would leak which workspaces exist.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  if (isPastRetention(org, DELETED_WORKSPACE_RETENTION_DAYS, new Date())) {
    throw new NotFoundError("Organization", orgId);
  }

  const actor: Actor = { userId, orgId, role: member.role };
  assertOrgScope(actor, org.id);
  assertCan(actor, "org:restore", orgResource(org.id));

  if (!isArchived(org)) return org;

  const restored = await orgRepo.restoreOrg(org.id);

  await announce("organization.restored", actorEnvelope(actor), restored);

  return restored;
}

/**
 * Publishes a deletion/restoration and makes sure it reaches the audit log.
 *
 * The audit row is normally written by the activity listeners reacting to the
 * event. Deleting or restoring a whole workspace must not go unaudited just
 * because the bus is not wired in this process (a script, a job), so when no
 * listener recorded it the row is written here instead — never both.
 */
async function announce(
  action: "organization.deleted" | "organization.restored",
  stamp: EventEnvelope,
  org: Organization,
): Promise<void> {
  const before = await countAudited(org.id, action);

  await emit(action, { ...stamp, slug: org.slug });

  if ((await countAudited(org.id, action)) > before) return;

  await record(org.id, action, {
    actorId: stamp.actorId,
    subjectKind: "organization",
    subjectId: org.id,
    projectId: null,
    summary:
      action === "organization.deleted"
        ? `Deleted workspace ${org.slug}`
        : `Restored workspace ${org.slug}`,
  });
}

