s=open(p).read()
s+='''
/**
 * Purges every workspace whose deletion is at least
 * `DELETED_WORKSPACE_RETENTION_DAYS` old at `now`. Not batched and not driven
 * by the usage work list: a workspace past its window must go on this pass
 * whether or not it ever had a usage row.
 */
async function purgeDeletedWorkspaces(
  now: Date,
  result: JobResult,
): Promise<void> {
  for (const org of await orgRepo.listDeletedOrgs()) {
    if (!isPastRetention(org, DELETED_WORKSPACE_RETENTION_DAYS, now)) continue;

    try {
      await orgRepo.purgeOrg(org.id);
      result.processed += 1;
      logger.info("deleted workspace purged", { orgId: org.id });
    } catch (error) {
      result.failed += 1;
      logger.error("workspace purge failed", {
        orgId: org.id,
        reason: error instanceof Error ? error.message : String(error),
      });
    }
  }
}
'''
