import * as sessionService from "@/server/services/session-service";
import { activityFilterSchema } from "@/schemas/activity";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { OrgId, SessionId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
const PAST = "2026-01-01T00:00:00.000Z";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function makeTenant(slug: string): Promise<Tenant> {
  const tenant = await createTenant(slug);
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function deleteTenant(tenant: Tenant) {
  return organizationService.deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

/** Moves a deletion into the past, as if it had happened `ms` before `now`. */
function backdateDeletion(orgId: OrgId, now: Date, ms: number): void {
  getDb()
    .$client.prepare("UPDATE organizations SET archived_at = ? WHERE id = ?")
    .run(new Date(now.getTime() - ms).toISOString(), orgId);
}

function countRows(table: string, orgId: OrgId): number {
  const row = getDb()
    .$client.prepare(`SELECT count(*) AS n FROM "${table}" WHERE org_id = ?`)
    .get(orgId) as { n: number };
  return row.n;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("deleting a workspace", () => {
  it("publishes organization.deleted and audits it once", async () => {
    const tenant = await makeTenant("del-event");
    const seen = capture("organization.deleted");

    const deleted = await deleteTenant(tenant);

    expect(deleted.archivedAt).not.toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: "del-event",
    });

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "organization",
      tenant.org.id,
    );
    expect(audit.map((row) => row.action)).toEqual(["organization.deleted"]);
    expect(audit[0]?.actorId).toBe(tenant.userIds.owner);
  });

  it("audits exactly once when the activity listeners are attached too", async () => {
    const tenant = await makeTenant("del-listeners");
    detachers.push(registerActivityListeners());

    await deleteTenant(tenant);
    await organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id);

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "organization",
      tenant.org.id,
    );
    expect(audit.map((row) => row.action).sort()).toEqual([
      "organization.deleted",
      "organization.restored",
    ]);
  });

  it("refuses to delete a workspace twice", async () => {
    const tenant = await makeTenant("del-twice");
    await deleteTenant(tenant);

    await expect(deleteTenant(tenant)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("accepts the new actions in the audit-log filter schema", () => {
    const parsed = activityFilterSchema.safeParse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      action: ["organization.deleted", "organization.restored"],
    });
    expect(parsed.success).toBe(true);
  });
});

describe("a deleted workspace", () => {
  it("cannot be signed in to, is not listed, and keeps its slug reserved", async () => {
    const tenant = await makeTenant("del-hidden");
    const { token } = await sessionService.createSessionToken(tenant.userIds.owner);
    const sessionId = getDb()
      .$client.prepare("SELECT id FROM sessions WHERE token_hash = ?")
      .get(hashToken(token)) as { id: string };
    await sessionRepo.setActiveOrg(sessionId.id as SessionId, tenant.org.id);

    await deleteTenant(tenant);

    const principal = await sessionService.resolveSession(token);
    expect(principal?.activeOrgId).toBeNull();
    expect(
      await sessionService.resolveActorForOrg(principal!, tenant.org.slug),
    ).toBeNull();
    expect(await resolveActor(tenant.userIds.owner, tenant.org.id)).toBeNull();
    await expect(
      sessionService.switchActiveOrg(principal!, { orgId: tenant.org.id }),
    ).rejects.toThrow();

    const listed = await organizationService.listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.map((org) => org.id)).not.toContain(tenant.org.id);

    const other = await organizationService.createOrganization(tenant.userIds.admin, {
      name: "Squatter",
      slug: "del-hidden",
      plan: "free",
    });
    expect(other.slug).not.toBe("del-hidden");

    await organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect((await sessionService.resolveSession(token))?.activeOrgId).toBe(tenant.org.id);
    expect(await resolveActor(tenant.userIds.owner, tenant.org.id)).not.toBeNull();
  });

  it("gets no notifications and accepts no invitations", async () => {
    const tenant = await makeTenant("del-inert");
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      { orgId: tenant.org.id, email: "new@del-inert.test", role: "member", expiresInDays: 7 },
      tenant.userIds.owner,
      hashToken("inert-token"),
    );
    const newcomer = await userRepo.insertUser({
      email: "new@del-inert.test",
      name: "Newcomer",
      passwordHash: "seed",
    });

    await deleteTenant(tenant);

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
      title: "t",
      body: "b",
      href: "/",
      actorId: tenant.userIds.owner,
    });
    expect(rows).toHaveLength(0);
    expect(countRows("notifications", tenant.org.id)).toBe(0);

    await expect(
      invitationService.acceptInvitation(newcomer.id, { token: "inert-token" }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.id)).toEqual([invitation.id]);
    expect(await memberRepo.findMember(tenant.org.id, newcomer.id)).toBeNull();

    await organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id);
    const member = await invitationService.acceptInvitation(newcomer.id, {
      token: "inert-token",
    });
    expect(member.orgId).toBe(tenant.org.id);
  });

  it("is left alone by every job until it is restored", async () => {
    const tenant = await makeTenant("del-jobs");
    const now = new Date();

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late",
        assigneeId: tenant.userIds.member,
        dueAt: PAST,
      }),
    );
    const endpoint = await webhookRepo.insertEndpoint(
      { orgId: tenant.org.id, url: "https://example.test/hook", eventTypes: ["issue.created"] },
      "secret",
    );
    const delivery = await webhookRepo.enqueueDelivery(
      tenant.org.id,
      endpoint.id,
      "issue.created",
      "{}",
    );
    getDb()
      .$client.prepare("UPDATE subscriptions SET current_period_end = ? WHERE org_id = ?")
      .run(PAST, tenant.org.id);
    getDb()
      .$client.prepare("UPDATE organization_usage SET seats_used = 1, projects_used = 0 WHERE org_id = ?")
      .run(tenant.org.id);

    await deleteTenant(tenant);
    const usageBefore = await usageRepo.getUsage(tenant.org.id);

    const overdue = capture("issue.overdue");
    await runOverdueIssueJob(now);
    await runUsageRollupJob(now);
    await runTrialExpiryJob(now);
    await runWebhookDeliveryJob(now);
    await runCleanupArchivedJob(now);

    expect(overdue.map((payload) => payload.issueId)).not.toContain(issue.id);
    expect(await usageRepo.listOrgIdsForRollup(1_000)).not.toContain(tenant.org.id);
    expect(await usageRepo.getUsage(tenant.org.id)).toEqual(usageBefore);
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.status).toBe("trialing");
    const failed = getDb()
      .$client.prepare("SELECT status FROM webhook_deliveries WHERE id = ?")
      .get(delivery.id) as { status: string };
    expect(failed.status).toBe("failed");
    expect(await orgRepo.findOrgById(tenant.org.id)).not.toBeNull();

    await organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id);

    await runOverdueIssueJob(now);
    await runUsageRollupJob(now);
    expect(overdue.map((payload) => payload.issueId)).toContain(issue.id);
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);
  });
});

describe("restoring a workspace", () => {
  it("is not found for an unknown workspace, a non-member, or a closed window", async () => {
    const tenant = await makeTenant("restore-404");
    const stranger = await makeTenant("restore-stranger");
    await deleteTenant(tenant);

    await expect(
      organizationService.restoreOrganization(
        tenant.userIds.owner,
        "01HZZZ00000000000000000000" as OrgId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      organizationService.restoreOrganization(stranger.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    backdateDeletion(tenant.org.id, new Date(), WINDOW_MS + 1_000);
    await expect(
      organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    // The window wins over the role check: gone is gone for everyone.
    await expect(
      organizationService.restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("requires the owner role", async () => {
    const tenant = await makeTenant("restore-role");
    await deleteTenant(tenant);

    await expect(
      organizationService.restoreOrganization(tenant.userIds.admin, tenant.org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("returns a live workspace unchanged and publishes nothing", async () => {
    const tenant = await makeTenant("restore-noop");
    const seen = capture("organization.restored");

    const org = await organizationService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );

    expect(org).toEqual(await orgRepo.findOrgById(tenant.org.id));
    expect(org.updatedAt).toBe(tenant.org.updatedAt);
    expect(seen).toHaveLength(0);
  });

  it("works until the window closes and publishes organization.restored", async () => {
    const tenant = await makeTenant("restore-ok");
    await deleteTenant(tenant);
    backdateDeletion(tenant.org.id, new Date(), WINDOW_MS - 60_000);

    const seen = capture("organization.restored");
    const restored = await organizationService.restoreOrganization(
      tenant.userIds.owner,
      tenant.org.id,
    );

    expect(restored.archivedAt).toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: "restore-ok",
    });
    expect((await orgRepo.findOrgBySlug("restore-ok"))?.id).toBe(tenant.org.id);
  });
});

describe("the retention sweep", () => {
  it("purges a workspace deleted the full window ago, and nothing younger or live", async () => {
    const doomed = await makeTenant("purge-doomed");
    const recent = await makeTenant("purge-recent");
    const live = await makeTenant("purge-live");
    const now = new Date();

    await issueService.createIssue(
      doomed.actors.member,
      issueInput(doomed.org.id, doomed.project.id, { title: "Goes too" }),
    );
    const { token } = await sessionService.createSessionToken(doomed.userIds.owner);
    const session = getDb()
      .$client.prepare("SELECT id FROM sessions WHERE token_hash = ?")
      .get(hashToken(token)) as { id: string };
    await sessionRepo.setActiveOrg(session.id as SessionId, doomed.org.id);

    await deleteTenant(doomed);
    await deleteTenant(recent);
    backdateDeletion(doomed.org.id, now, WINDOW_MS);
    backdateDeletion(recent.org.id, now, WINDOW_MS - 1);

    await runCleanupArchivedJob(now);

    expect(await orgRepo.findOrgById(doomed.org.id)).toBeNull();
    for (const table of [
      "members",
      "invitations",
      "projects",
      "project_members",
      "issues",
      "labels",
      "issue_labels",
      "comments",
      "attachments",
      "notifications",
      "notification_preferences",
      "activity_events",
      "subscriptions",
      "invoices",
      "webhook_endpoints",
      "webhook_deliveries",
      "search_index",
      "organization_usage",
      "rate_limit_buckets",
    ]) {
      expect(countRows(table, doomed.org.id), table).toBe(0);
    }

    expect(await userRepo.findUserById(doomed.userIds.owner)).not.toBeNull();
    const activeOrg = getDb()
      .$client.prepare("SELECT active_org_id FROM sessions WHERE id = ?")
      .get(session.id) as { active_org_id: string | null };
    expect(activeOrg.active_org_id).toBeNull();
    expect((await sessionService.resolveSession(token))?.activeOrgId).toBeNull();

    await expect(
      organizationService.restoreOrganization(doomed.userIds.owner, doomed.org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await usageRepo.listOrgIdsForRollup(1_000)).not.toContain(doomed.org.id);

    const reborn = await organizationService.createOrganization(doomed.userIds.owner, {
      name: "Reborn",
      slug: "purge-doomed",
      plan: "free",
    });
    expect(reborn.slug).toBe("purge-doomed");

    expect((await orgRepo.findOrgById(recent.org.id))?.archivedAt).not.toBeNull();
    expect(countRows("members", recent.org.id)).toBe(4);
    expect((await orgRepo.findOrgById(live.org.id))?.archivedAt).toBeNull();
    expect(countRows("members", live.org.id)).toBe(4);
  });
});

