import type { OrgId, SessionId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const WINDOW_MS = DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
const PAST = "2026-01-01T00:00:00.000Z";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function makeTenant(slug: string): Promise<Tenant> {
  const tenant = await createTenant(slug);
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

async function deleteTenant(tenant: Tenant) {
  return organizationService.deleteOrganization(tenant.actors.owner, {
    orgId: tenant.org.id,
    confirmSlug: tenant.org.slug,
  });
}

/** Moves a deletion into the past, as if it had happened `ms` before `now`. */
function backdateDeletion(orgId: OrgId, now: Date, ms: number): void {
  getDb()
    .$client.prepare("UPDATE organizations SET archived_at = ? WHERE id = ?")
    .run(new Date(now.getTime() - ms).toISOString(), orgId);
}

function countRows(table: string, orgId: OrgId): number {
  const row = getDb()
    .$client.prepare(`SELECT count(*) AS n FROM "${table}" WHERE org_id = ?`)
    .get(orgId) as { n: number };
  return row.n;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("deleting a workspace", () => {
  it("publishes organization.deleted and audits it once", async () => {
    const tenant = await makeTenant("del-event");
    const seen = capture("organization.deleted");

    const deleted = await deleteTenant(tenant);

    expect(deleted.archivedAt).not.toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      slug: "del-event",
    });

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
