    expect(audit[0]?.actorId).toBe(tenant.userIds.owner);
  });

  it("audits exactly once when the activity listeners are attached too", async () => {
    const tenant = await makeTenant("del-listeners");
    detachers.push(registerActivityListeners());

    await deleteTenant(tenant);
    await organizationService.restoreOrganization(tenant.userIds.owner, tenant.org.id);

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
