"use server";

/**
 * Restores a deleted organization while its grace period is open.
 *
 * Owner D. Unlike every other organization action this one cannot go through
 * `withAction()`: no `Actor` can be resolved for a deleted workspace, so the
 * caller is identified by the session's user id and `restoreOrganization()`
 * performs the membership, grace-period and `org:restore` checks itself.
 *
 * Must call (do not reimplement): restoreOrganizationSchema, toActionResult
 */

import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import { restoreOrganizationSchema } from "@/schemas/organization";
import { restoreOrganization } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";
import { revalidatePath } from "next/cache";

export async function restoreOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  const parsed = restoreOrganizationSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const principal = await getSessionPrincipal();
    if (principal === null) {
      throw new UnauthorizedActionError();
    }

    const organization = await restoreOrganization(
      principal.userId,
      parsed.data.orgId,
    );

    revalidateTagged([orgTag(organization.id)], CACHE_PROFILES.minutes);
    revalidatePath("/orgs");
    return {
      ok: true,
      data: organization,
      submittedAt: new Date().toISOString(),
    };
  } catch (error) {
    return toActionResult(error);
  }
}
EOF
